def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    tiles = [(r0, r1, c0, c1) for r0, r1 in row_ranges for c0, c1 in col_ranges]
    src = max(
        tiles,
        key=lambda t: sum(grid[r][c] != bg for r in range(t[0], t[1]) for c in range(t[2], t[3]))
    )
    r0, r1, c0, c1 = src
    pattern = [row[c0:c1] for row in grid[r0:r1]]

    out = [row[:] for row in grid]
    for a, b, x, y in tiles:
        if (a, b, x, y) == src:
            continue
        for i, r in enumerate(range(a, b)):
            for j, c in enumerate(range(x, y)):
                out[r][c] = pattern[i][j]
    return out
